import{_ as t,o,c as d,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Production Operations & AWS Infrastructure Runbooks (docs/operations/)","description":"","frontmatter":{},"headers":[],"relativePath":"operations/README.md","filePath":"operations/README.md"}'),a={name:"operations/README.md"};function c(n,e,i,s,l,g){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="production-operations-aws-infrastructure-runbooks-docs-operations" tabindex="-1">Production Operations &amp; AWS Infrastructure Runbooks (<code>docs/operations/</code>) <a class="header-anchor" href="#production-operations-aws-infrastructure-runbooks-docs-operations" aria-label="Permalink to &quot;Production Operations &amp; AWS Infrastructure Runbooks (`docs/operations/`)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./../architecture/README.html">System Architecture</a> · <a href="./../database/README.html">Database Architecture</a></p><p>Authoritative operational runbooks for BrandHub&#39;s <strong>AWS <code>ap-southeast-1</code> (Singapore) Production Environment</strong> (Account <code>134875421878</code>) and <strong>Vast.ai GPU Synthesis Workers</strong>. Executable Terraform stacks (<code>01-iam</code> → <code>04-storage</code>), per-host Docker Compose manifests, Nginx reverse-proxy rules, and systemd units reside at the repository root under <code>prod/</code> (<code>prod/README.md</code>, <code>prod/hosts/README.md</code>, <code>prod/terraform/README.md</code>) and <code>gpu-workers/</code> (<code>gpu-workers/README.md</code>).</p><hr><h2 id="_1-live-production-topology-ap-southeast-1-account-134875421878" tabindex="-1">1. Live Production Topology (<code>ap-southeast-1</code>, Account <code>134875421878</code>) <a class="header-anchor" href="#_1-live-production-topology-ap-southeast-1-account-134875421878" aria-label="Permalink to &quot;1. Live Production Topology (`ap-southeast-1`, Account `134875421878`)&quot;">​</a></h2><h3 id="_1-1-five-host-ec2-compute-fleet-cloudfront-edge" tabindex="-1">1.1 Five-Host EC2 Compute Fleet &amp; CloudFront Edge <a class="header-anchor" href="#_1-1-five-host-ec2-compute-fleet-cloudfront-edge" aria-label="Permalink to &quot;1.1 Five-Host EC2 Compute Fleet &amp; CloudFront Edge&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Host Role</th><th style="text-align:left;">EC2 Instance ID</th><th style="text-align:left;">Private IP</th><th style="text-align:left;">Instance Type</th><th style="text-align:left;">Key Containers &amp; Systemd Units (<code>prod/hosts/</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>gateway</code></strong></td><td style="text-align:left;"><code>i-05f5bfca4452b0f83</code></td><td style="text-align:left;"><code>172.31.27.199</code></td><td style="text-align:left;"><code>t3.small</code></td><td style="text-align:left;">Host/container <strong>Nginx</strong> (<code>80/443</code>, Let&#39;s Encrypt TLS for <code>api.brandhub.id.vn</code> via <code>brandhub-certificate-renew.timer</code>), <strong><code>brandhub-api-gateway</code></strong> (<code>:8080</code>), <strong><code>edit-video</code> waker</strong> (<code>:8099</code>)</td></tr><tr><td style="text-align:left;"><strong><code>core</code></strong></td><td style="text-align:left;"><code>i-01cba58d9f08be748</code></td><td style="text-align:left;"><code>172.31.24.149</code></td><td style="text-align:left;"><code>m7i-flex.large</code></td><td style="text-align:left;"><strong><code>brandhub-business-service</code></strong> (<code>:8081</code>), <strong><code>brandhub-publisher-service</code></strong> (<code>:8083</code>), <strong>PostgreSQL 17</strong>, <strong>Redis 7</strong>, <strong>RabbitMQ 3.13</strong>, <strong>ChromaDB</strong>, <strong><code>db-backup</code></strong> (<code>:8090</code>, 00:00 ICT S3 dumps), <strong><code>crawl-gate</code></strong> (<code>:8084</code>) + <strong><code>crawl</code> waker</strong></td></tr><tr><td style="text-align:left;"><strong><code>ai</code></strong></td><td style="text-align:left;"><code>i-0f7857edf71b6bb3f</code></td><td style="text-align:left;"><code>172.31.20.60</code></td><td style="text-align:left;"><code>c7i-flex.large</code></td><td style="text-align:left;">Dedicated <strong><code>brandhub-ai-service</code></strong> (<code>:8082</code>, <code>3 GiB</code> container limit) connected to <code>core</code> stores via VPC security-group rules (<code>brandhub-ai-sg</code>) and MongoDB Atlas</td></tr><tr><td style="text-align:left;"><strong><code>crawl</code></strong></td><td style="text-align:left;"><code>i-0288d396a5d5b9b06</code></td><td style="text-align:left;"><code>172.31.20.50</code></td><td style="text-align:left;"><code>c7i-flex.large</code></td><td style="text-align:left;"><strong><code>crawl-service</code></strong> (<code>:8084</code>, Playwright/Camoufox). Auto-sleeps via <code>brandhub-idle-sleep.timer</code>; wakes on demand via <code>crawl-gate</code> or EventBridge <code>07:00</code>/<code>19:00</code> ICT schedule (<code>crawl-kick.sh</code>)</td></tr><tr><td style="text-align:left;"><strong><code>edit-video</code></strong></td><td style="text-align:left;"><code>i-0ec7bf59c53fb7d0b</code></td><td style="text-align:left;"><code>172.31.20.80</code></td><td style="text-align:left;"><code>m7i-flex.large</code></td><td style="text-align:left;"><strong><code>brandhub-edit-video</code></strong> (<code>:8095</code>, FFmpeg server timeline renderer). Auto-sleeps after 30 idle minutes; wakes on HTTP request via <code>gateway</code> Nginx <code>502/504 -&gt; 503 STARTING</code></td></tr></tbody></table><h3 id="_1-2-storage-cdn-iam-gpu-inference-tiers" tabindex="-1">1.2 Storage, CDN, IAM &amp; GPU Inference Tiers <a class="header-anchor" href="#_1-2-storage-cdn-iam-gpu-inference-tiers" aria-label="Permalink to &quot;1.2 Storage, CDN, IAM &amp; GPU Inference Tiers&quot;">​</a></h3><ul><li><strong>Frontend Edge (<code>02-frontend</code>)</strong>: S3 bucket <code>brandhub-web-prd-134875421878</code> fronted by CloudFront (<code>brandhub.id.vn</code>) with CloudFront Function <code>brandhub-public-routes.js</code> rewriting SPA routes while preserving public <code>/s/:token</code> share links.</li><li><strong>Media &amp; KMS Vault Storage (<code>04-storage</code>)</strong>: <ul><li><code>brandhub-media-134875421878</code> — private repository &amp; Client Vault bucket encrypted with KMS key <code>alias/brandhub-repository-media-prod</code> + <code>RepositoryEnvelopeCrypto</code>.</li><li><code>brandhubmedia-134875421878</code> — rendered public social/image delivery bucket.</li><li><code>brandhub-db-backup-prd-134875421878</code> — encrypted nightly PostgreSQL (<code>pg_dump -Fc</code>) and MongoDB (<code>mongodump --archive --gzip</code>) backups written by <code>prod/hosts/core/db-backup/</code>.</li></ul></li><li><strong>Zero Static AWS Keys on EC2 (<code>01-iam</code>)</strong>: Services authenticate exclusively via EC2 Instance Profile <code>brandhub-ec2-ecr-pull</code> (<code>DefaultCredentialsProvider</code> in Java, <code>boto3</code> IMDSv2 role credentials in Python); only external Vast.ai GPU workers use scoped IAM user <code>brandhub-worker-s3-uploader</code>.</li><li><strong>External GPU Synthesis (<code>gpu-workers/wan-vace/</code>)</strong>: Vast.ai GPU nodes running ComfyUI + <strong>Wan 2.2 Fun VACE 14B + Wan 2.2 S2V 14B + Qwen Image 2.1</strong> + Ollama <code>qwen2.5vl:7b</code>.</li></ul><hr><h2 id="_2-active-runbooks" tabindex="-1">2. Active Runbooks <a class="header-anchor" href="#_2-active-runbooks" aria-label="Permalink to &quot;2. Active Runbooks&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Runbook</th><th style="text-align:left;">Scope</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./deployment-acct134.html">deployment-acct134.md</a></td><td style="text-align:left;"><strong>Primary Production Runbook</strong>: 5-EC2 inventory, ECR <code>sha-&lt;commit&gt;-acct134</code> image pinning, S3 KMS repository setup, PostgreSQL restore log, AI host isolation, and Vast.ai worker deployment notes</td></tr><tr><td style="text-align:left;"><a href="./wake-on-request.html">wake-on-request.md</a></td><td style="text-align:left;"><strong>Auto-Sleep &amp; Wake-on-Request Architecture</strong>: Zero-dependency <code>waker.py</code> (SigV4 + IMDSv2), Nginx <code>error_page 502 504 = @wake</code> fallback (<code>503 {&quot;status&quot;:&quot;STARTING&quot;}</code> + <code>Retry-After: 60</code>), EventBridge <code>07:00/19:00</code> ICT crawl schedule, and <code>brandhub-idle-sleep.timer</code></td></tr></tbody></table><hr><h2 id="_3-chronological-migration-profiling-history-history" tabindex="-1">3. Chronological Migration &amp; Profiling History (<code>history/</code>) <a class="header-anchor" href="#_3-chronological-migration-profiling-history-history" aria-label="Permalink to &quot;3. Chronological Migration &amp; Profiling History (`history/`)&quot;">​</a></h2><p>Historical deployment and capacity engineering logs leading up to the current 5-host topology:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Date</th><th style="text-align:left;">Log Document</th><th style="text-align:left;">Engineering Summary</th></tr></thead><tbody><tr><td style="text-align:left;"><code>2026-10-29</code></td><td style="text-align:left;"><a href="./history/2026-10-29-ecr-deploy.html">history/2026-10-29-ecr-deploy.md</a></td><td style="text-align:left;">Initial immutable ECR deployment baseline, Let&#39;s Encrypt certificate renewal systemd timer, and Meta/TikTok/Threads OAuth callback verification</td></tr><tr><td style="text-align:left;"><code>2026-11-03</code></td><td style="text-align:left;"><a href="./history/2026-11-03-rebalance-ai.html">history/2026-11-03-rebalance-ai.md</a></td><td style="text-align:left;">Zero-data-loss migration of <code>brandhub-ai-service</code> and HuggingFace/PhoBERT model cache volumes onto a dedicated compute host</td></tr><tr><td style="text-align:left;"><code>2026-11-03</code></td><td style="text-align:left;"><a href="./history/2026-11-03-crawl-ram-check.html">history/2026-11-03-crawl-ram-check.md</a></td><td style="text-align:left;">Post-migration Linux cgroup memory profiling during authenticated Playwright Facebook &amp; Threads crawler runs</td></tr></tbody></table>',16)])])}const p=t(a,[["render",c]]);export{h as __pageData,p as default};
